from _lib import *
u1=U("conditions","Offers and conditions","B2",
 "Negotiation is built on conditions. Use if + past with would for tentative offers, and provided that, as long as and unless to set your terms clearly.",
 "দরকষাকষি শর্তের উপর চলে। নরম প্রস্তাবে If you could…, we would…; শর্ত দিতে provided that, as long as, unless।",
 [("Tentative offer","If you could pay in advance, we would give you a 5% discount."),("Firm offer","If you order 500 units, we'll include free delivery."),("Conditions","provided that / as long as + present · unless = if not")],
 [("If + past, would: a softer, hypothetical offer.","If + past, would দিয়ে নরম প্রস্তাব।","If you signed today, we would hold this price for a year."),
  ("If + present, will: a real, firm offer.","নিশ্চিত প্রস্তাবে If + present, will।","If you confirm by Friday, we'll start next month."),
  ("Provided that / as long as + present tense, not will.","provided that / as long as এর পরে present, will নয়।","We can deliver in May, as long as you send the designs this week."),
  ("Unless = except if; don't add another negative.","unless মানে 'যদি না'; আবার not যোগ করবেন না।","We can't lower the price unless you increase the order."),
  ("Trade: give something to get something.","কিছু দিয়ে কিছু নিন।","If you could extend the contract to two years, we'd be able to reduce the monthly fee.")],
 ["if you could","we would","provided that","as long as","unless","in return"],
 [("If you will pay early, we give discount.","If you pay early, we'll give you a discount.","No will after if; future in the main clause.","if এর পরে will নয়।"),
  ("Unless you don't pay, we won't ship.","Unless you pay, we won't ship.","Unless already means 'if not'.","unless এর সাথে don't দিলে দ্বি-নেতিবাচক হয়।"),
  ("As long as you will sign, we agree.","As long as you sign, we're happy to agree.","Present tense after as long as.","as long as এর পরে present।")],
 [C("A tentative offer to a client.","If you ___ pay half up front, we would start next week.",["could","can will","would to","will could"],"could","If you could…, we would…"),
  T("A firm, real offer.","If you order today, we ___ deliver free of charge.","will",["will","'ll"],"If + present, will."),
  C("Condition.","We can agree to the price ___ you sign a one-year contract.",["provided that","unless","even if","in case of"],"provided that","Provided that = only if."),
  F("Pick the correct sentence.",["Unless you don't confirm by Monday, we'll cancel.","Unless you confirm by Monday, we'll cancel the booking.","Unless you will confirm by Monday, we cancel.","If you not confirm by Monday, we cancel."],"Unless you confirm by Monday, we'll cancel the booking.","Unless = if not.",True),
  B("আপনারা যদি অর্ডার দ্বিগুণ করেন, আমরা দাম ১০% কমাতে পারি।",["If you doubled the order, we could lower the price by 10%.","If you will double order, we can less the price 10%.","If you double the order, we could lowered the price 10%.","If you doubled order, we can to reduce 10% price."],"If you doubled the order, we could lower the price by 10%.","If + past, could."),
  T("Condition with present tense.","We'll finish on time as long as the client ___ the content by Friday.","send",["sends"],"Present after as long as."),
  C("Negotiating at a garment buyer meeting.","___ you could accept a later delivery date, we would be able to cut costs.",["If","Unless","Despite","Even"],"If","If you could…"),
  B("যতক্ষণ মান ঠিক থাকে, আমরা রাজি।",["As long as the quality stays the same, we're happy to agree.","As long as the quality will be same, we are agree.","Unless the quality stays the same, we agree.","So long the quality same, we agreed."],"As long as the quality stays the same, we're happy to agree.","As long as + present.",True)])
u2=U("persuade","Softening and persuading","C1",
 "Strong negotiators sound flexible but firm. Soften proposals with we'd be willing to, would you consider and we might be able to, then persuade with clear reasons and comparisons.",
 "ভালো আলোচক নমনীয় কিন্তু দৃঢ়। we'd be willing to, would you consider দিয়ে প্রস্তাব নরম করুন, তারপর কারণ আর তুলনা দিয়ে বোঝান।",
 [("Soften","We'd be willing to… · Would you consider…? · We might be able to… · I'm not sure we could go that far."),("Persuade","The main advantage is… · It's far more reliable than… · In the long run, you'd save…")],
 [("We'd be willing to + verb: a flexible offer.","নমনীয় প্রস্তাব: we'd be willing to + verb।","We'd be willing to split the delivery cost."),
  ("Would you consider + -ing?: a soft proposal.","Would you consider এর পরে -ing।","Would you consider extending the deadline by a week?"),
  ("Reject softly: I'm afraid that's a bit more than we can manage.","নরমভাবে প্রত্যাখ্যান করুন।","I'm afraid that's a little higher than our budget allows."),
  ("Compare with much/far + comparative.","তুলনা জোরালো করতে much/far + comparative।","Our system is far cheaper to maintain than the old one."),
  ("Give a reason and a long-term benefit.","কারণ আর দীর্ঘমেয়াদি সুবিধা বলুন।","It costs more up front, but you'd save a lot in the long run.")],
 ["we'd be willing to","would you consider","might be able to","far more","in the long run","the main advantage"],
 [("Would you consider to extend the deadline?","Would you consider extending the deadline?","Consider + -ing.","consider এর পরে -ing।"),
  ("Our price is more cheaper.","Our price is much cheaper.","Don't use more with -er.","more আর -er একসাথে নয়।"),
  ("This is our final price, take it or leave it.","I'm afraid this is the best we can offer at the moment.","Too aggressive; it can end the deal.","খুব কড়া; চুক্তি ভেঙে যেতে পারে।")],
 [C("A flexible offer.","We'd be ___ to cover half of the shipping cost.",["willing","agree","ready for","wanting"],"willing","Be willing to + verb."),
  T("A soft proposal.","Would you consider ___ the payment into two parts?","split",["splitting"],"Consider + -ing."),
  F("Pick the most natural and polite way to reject a price.",["That price is crazy.","No. Too expensive.","I'm afraid that's a bit higher than our budget allows. Is there any flexibility?","You are cheating us."],"I'm afraid that's a bit higher than our budget allows. Is there any flexibility?","Soft rejection + open question."),
  C("Comparison.","Our software is ___ faster than the one you're using now.",["much","more","very","most"],"much","Much + comparative."),
  B("দীর্ঘমেয়াদে আপনার অনেক টাকা বাঁচবে।",["In the long run, you'd save a lot of money.","In long term, you will save many money.","In the long run, you would saved a lot of money.","For a long time, you save much money."],"In the long run, you'd save a lot of money.","In the long run = over time."),
  C("Leaving room to agree later.","We ___ be able to offer free installation if you sign this month.",["might","must","should to","can to"],"might","Might be able to = tentative."),
  T("Comparative.","This plan is far ___ reliable than the cheaper option.","much",["more"],"Far more + adjective."),
  F("Pick the most persuasive sentence for a client.",["Buy ours, it is best.","Our product is more better than others.","The main advantage is that our machines use 30% less power, so your bills would be much lower.","Everybody buys this, so you also buy."],"The main advantage is that our machines use 30% less power, so your bills would be much lower.","Clear benefit with a reason.",True),
  B("আমরা হয়তো ডেলিভারির সময় এক সপ্তাহ এগিয়ে আনতে পারি।",["We might be able to bring the delivery forward by a week.","We may can prepone the delivery one week.","We might able to bring forward delivery a week.","Maybe we can to bring the delivery before one week."],"We might be able to bring the delivery forward by a week.","Might be able to + bring forward.",True)])
save("negotiate","Persuading and negotiating",
 "Whether you're agreeing a price with a buyer or asking your manager for more time, negotiation is about clear conditions and a flexible tone. Learn to make offers, set terms, soften proposals and give convincing reasons.",
 "দাম ঠিক করা হোক বা বসের কাছে সময় চাওয়া, দরকষাকষিতে দরকার স্পষ্ট শর্ত আর নমনীয় সুর। প্রস্তাব দেওয়া, শর্ত বলা আর যুক্তি দিয়ে বোঝানোর ইংরেজি শিখুন।",[u1,u2],
 [C("Tentative offer.","If you could wait two more weeks, we ___ reduce the price.",["could","can will","will be","are"],"could","If + past, could/would."),
  T("Condition.","We'll accept the terms provided that payment ___ within 30 days.","be made",["is made"],"Present after provided that."),
  F("Pick the correct sentence.",["Unless you don't agree, we'll go ahead.","Unless you object, we'll go ahead.","Unless you will object, we go ahead.","Unless not you object, we'll go ahead."],"Unless you object, we'll go ahead.","Unless = if not."),
  B("আপনি কি চুক্তিটা দুই বছরের জন্য করার কথা ভাববেন?",["Would you consider signing a two-year contract?","Would you consider to sign a two-year contract?","Will you think to make contract for two years?","Would you considering sign two-year contract?"],"Would you consider signing a two-year contract?","Consider + -ing."),
  F("Pick the most natural and polite reply to a low offer.",["That's an insult.","No way, too low.","I appreciate the offer, but I'm afraid we couldn't go below 50,000 taka.","Give more money."],"I appreciate the offer, but I'm afraid we couldn't go below 50,000 taka.","Thanks + soft but firm limit."),
  C("Comparison.","This option is ___ cheaper in the long run.",["far","more","very more","most"],"far","Far + comparative.")])
